.modal {
  width: min(400px, calc(100vw - 32px));
  padding: var(--space-6, 24px);
  border: 1px solid var(--color-border-default, #d4d4d4);
  border-radius: var(--radius-lg, 12px);
  background: var(--color-surface-overlay, #fff);
  color: var(--color-text-primary, #0a0a0a);
  box-shadow: var(--shadow-overlay, 0 24px 48px -12px rgba(0,0,0,.25));
}
.modal::backdrop { background: var(--color-scrim, rgba(0,0,0,.5)); }
.modal__header { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.modal__title { margin: 0; font-size: 20px; line-height: 1.3; }
.modal__close { border: 0; background: none; font-size: 24px; line-height: 1; cursor: pointer; color: inherit; }
.modal__body { margin: 12px 0 24px; line-height: 1.5; }
.modal__actions { display: flex; justify-content: flex-end; gap: 8px; }
