document.querySelectorAll('[data-open-modal]').forEach(trigger => {
  const modal = trigger.nextElementSibling;
  const isDialog = modal.tagName === 'DIALOG';
  const focusable = () => [...modal.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])')];
  const open = () => { if (isDialog) modal.showModal(); else { modal.hidden = false; focusable()[0].focus(); } };
  const close = () => { if (isDialog) modal.close(); else { modal.hidden = true; trigger.focus(); } };
  trigger.addEventListener('click', open);
  modal.addEventListener('click', e => {
    if (e.target === modal) close();                         /* click on the backdrop */
    else if (e.target.closest('button')) close();            /* Cancel, Close or Delete: run your action first */
  });
  if (!isDialog) modal.addEventListener('keydown', e => {
    if (e.key === 'Escape') close();
    if (e.key === 'Tab') {                                   /* keep focus inside while open */
      const f = focusable(), first = f[0], last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    }
  });
});
